import { confirmQuestion, installHistoryControls } from "./history-controls.js";
const applyInfolensTheme=(theme)=>document.documentElement.dataset.theme=theme;applyInfolensTheme(workspaceTheme());observeWorkspaceTheme(applyInfolensTheme);const api=new URLSearchParams(location.search).get("apiBaseUrl");const $=(selector)=>document.querySelector(selector);let data;let historyControls;
async function request(route,options){const response=await fetch(new URL(route,api),options);if(!response.ok)throw new Error(`Plugin API returned ${response.status}`);return response.json()}
function productRow(product,readOnly=false){const li=document.createElement("li");li.className=`product${product.read?" is-read":""}`;const rank=document.createElement("span");rank.className="rank";rank.textContent=String(product.rank).padStart(2,"0");const content=document.createElement("button");content.className="product-link";content.innerHTML=`<strong></strong><span>producthunt.com</span>`;content.querySelector("strong").textContent=product.name;content.onclick=async()=>{window.open(product.url,"_blank","noopener");if(readOnly)return;data=await request(`read?url=${encodeURIComponent(product.url)}`,{method:"POST"});render(data)};const votes=document.createElement("span");votes.className="votes";votes.textContent=`▲ ${product.votes}`;li.append(rank,content,votes);return li}
function render(next){data=next;const products=next.products??[];const disconnected=next.dependencyState==="disconnected";$("#dependency").hidden=!disconnected;document.querySelector("main").hidden=disconnected;$("#products").replaceChildren(...products.map(productRow));$("#products").hidden=!products.length;$("#empty").hidden=Boolean(products.length);$("#warning").hidden=!next.lastError||disconnected;const date=next.lastSuccessfulRefresh&&new Date(next.lastSuccessfulRefresh);$("#refresh-time").textContent=date?`Updated ${new Intl.DateTimeFormat("en",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}).format(date)}`:"Not refreshed yet";$("#refresh").disabled=next.settings?.policy==="disabled"}
async function load(){if(!api)throw new Error("Missing plugin API configuration");render(await request("summary"))}
