function showSettings(show){$(".workspace").inert=show;$("#sheet").hidden=!show;$("#scrim").hidden=!show;if(show){document.querySelector(`[name=policy][value=${data.settings.policy}]`).checked=true;$("#interval").value=data.settings.intervalMinutes;$("#retention").value=data.settings.retentionDays;$("#interval").disabled=data.settings.policy!=="fixed";$("#sheet input:checked").focus()}else $("#settings").focus()}
$("#refresh").onclick=$("#retry").onclick=$("#empty-refresh").onclick=$("#dependency-retry").onclick=refresh;$("#settings").onclick=()=>showSettings(true);$("#close-settings").onclick=$("#cancel-settings").onclick=$("#scrim").onclick=()=>showSettings(false);document.querySelectorAll("[name=policy]").forEach((radio)=>radio.onchange=()=>$("#interval").disabled=radio.value!=="fixed");$("#settings-form").onsubmit=async(event)=>{event.preventDefault();const form=new FormData(event.currentTarget);const retentionDays=Number(form.get("retentionDays"));const shorter=retentionDays<data.settings.retentionDays;if(shorter&&!await confirmQuestion("Shortening retention permanently deletes older snapshots. Continue?","Continue","Cancel"))return;await request(`settings?policy=${form.get("policy")}&intervalMinutes=${form.get("intervalMinutes")}&retentionDays=${retentionDays}&acknowledgeRetentionCleanup=${shorter}`,{method:"POST"});render(await request("summary"));showSettings(false)};addEventListener("keydown",(event)=>{if(event.key==="Escape"&&!$("#sheet").hidden)showSettings(false)});const retentionLabel=document.createElement("label");retentionLabel.htmlFor="retention";retentionLabel.textContent="History retention";const retention=document.createElement("select");retention.id="retention";retention.name="retentionDays";retention.innerHTML='<option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option>';$("#settings-form").insertBefore(retentionLabel,$(".sheet-actions"));$("#settings-form").insertBefore(retention,$(".sheet-actions"));historyControls=installHistoryControls({api,actions:document.querySelector(".actions"),locale:"en",onSnapshot:(detail)=>{const products=detail.records??[];$("#products").replaceChildren(...products.map(product=>productRow(product,true)));$("#products").hidden=!products.length;$("#empty").hidden=Boolean(products.length);$("#warning").hidden=true},onCurrent:()=>render(data)});load().catch((error)=>$("#products").innerHTML=`<li class="loading">${error.message}</li>`);
